<?php include '../includes/header.php';$u=user();$id=(int)($_GET['id']??0);if(is_admin()){$s=mysqli_prepare($conn,"SELECT r.*,u.name owner_name FROM records r JOIN users u ON u.id=r.owner_id WHERE r.id=?");mysqli_stmt_bind_param($s,'i',$id);}else{$s=mysqli_prepare($conn,"SELECT r.*,u.name owner_name FROM records r JOIN users u ON u.id=r.owner_id WHERE r.id=? AND r.institution_type=? AND r.institution_code=?");mysqli_stmt_bind_param($s,'iss',$id,$u['institution_type'],$u['institution_code']);}mysqli_stmt_execute($s);$x=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if(!$x)exit('Record not found or access denied.');?>
